#!/usr/bin/env bash
# Step 5 – writes deploy/helm/intimed/values-<env>.generated.yaml from `terraform output` (no secrets in it).
source "$(dirname "$0")/common.sh"
need terraform jq
OUT="$ROOT/deploy/helm/intimed/values-$ENV.generated.yaml"
J=$(terraform -chdir="$TF_DIR" output -json)
v() { echo "$J" | jq -r ".$1.value"; }
cat > "$OUT" <<YAML
# generated by deploy/azure/scripts/render-values.sh – $(date -u +%FT%TZ)
image:
  repository: $(v acr_login_server)/intimed/platform
  tag: "${IMAGE_TAG:-2.2.0}"
  digest: "${IMAGE_DIGEST:-}"
azure:
  tenantId: $(v tenant_id)
  workloadIdentityClientId: $(v workload_identity_client_id)
  keyVaultName: $(v key_vault_name)
  keyVaultUri: $(v key_vault_uri)
  archiveAccountUrl: $(v archive_account_url | sed 's#/$##')
database:
  host: $(v postgres_fqdn)
console:
  loadBalancerIP: $(v console_lb_ip)
  subnetName: snet-aks
devices:
  loadBalancerIP: $(v devices_lb_ip)
  subnetName: snet-devices
  dnsName: "${DEVICES_DNS_NAME:-}"
networkPolicy:
  appGatewaySubnetCidr: $(v subnet_cidrs | jq -r .appgw)
  postgresSubnetCidr: $(v subnet_cidrs | jq -r .postgres)
  privateEndpointSubnetCidr: $(v subnet_cidrs | jq -r .endpoints)
  deviceSourceCidrs: $(v device_source_cidrs | jq -c .)
YAML
echo "wrote $OUT"
